            0x75: 0x68,  # WHO_AM_I
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr}")

        value = self.regs[addr]

        # Handle single-byte access
        if nbytes == 1:
            if addr == 0x75:
                # WHO_AM_I has a special case for reading lower 8 bits
                return value & 0xFF
            else:
                # For other RO registers, return the entire 16-bit value
                return value

        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr}")

        # Ignore writes to RO registers
        if self.regs[addr] & 0x8000 == 0x8000:
