        if nbytes == 1:
            if addr == 0x19 or addr == 0x1A or addr == 0x1B or addr == 0x1C:
                # For writable registers, update only the specified bits
                mask = (1 << addr % 16) - 1
                self.regs[addr] = (self.regs[addr] & ~mask) | (data & mask)
            elif addr == 0x75:
                # WHO_AM_I has a special case for writing lower 8 bits
                self.regs[addr] = (self.regs[addr] & 0xF0) | (data & 0xFF)
            else:
