    def __init__(self):
        self.regs = {}
        self.initialize_registers()

    def initialize_registers(self):
        for reg in self.get_ir()['registers']:
            addr = reg['addr']
            value = reg['reset']
            if 'runtime_value' in reg:
                value = self.generate_runtime_value(addr)
            self.regs[addr] = value

    def generate_runtime_value(self, addr):
        if addr == 'ACCEL_XOUT_H':
            return 0b1010101010101010  # Example runtime value for ACCEL_XOUT_H
        elif addr == 'ACCEL_XOUT_L':
            return 0b1111111111111111  # Example runtime value for ACCEL_XOUT_L
        else:
            return 0

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Unknown register address: {addr}")

        if nbytes == 1:
            return self.regs[addr] & 0xFF  # Return only the lower 8 bits

        return self.regs[addr]

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Unknown register address: {addr}")

        if nbytes == 1:
            # Update only the lower 8 bits of the existing value
            self.regs[addr] &= ~0xFF
            self.regs[addr] |= data & 0xFF
        else:
            self.regs[addr] = data
